sub parse_imports {
    my ($content, $file) = @_;
    my %imps;
    if ($content =~ /^package\s+(\w+)/m) {
        $file_pkg{$file} = $1;
    }
    while ($content =~ /^import\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)")/mg) {
        my $block = $1 // '';
        my $single = $2 // '';
