my (%file_pkg,%file_imports,%decls);

sub pkg_path { my $f=shift; $f=~s{^\Q$root\E/}{}; $f=~s{/[^/]+$}{}; "$module/$f"; }

for my $file (@go_files) {
  open my $fh,'<',$file or next; my $c=do{local $/;<$fh>}; close $fh;
  $file_pkg{$file}=$1 if $c=~/^package\s+(\w+)/m;
  my %imps; while ($c=~/^import\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)")/mg) {
    my @ls=defined$2?qq{"$2"}:split/\n/,$1//''; for(@ls){next unless/"([^"]+)"/; my($p,$a)=($1,basename($1)); $a=~s/-/_/g; $a=$1 if/^\s*(\w+)\s+"/; $imps{$a}=$p;}
  } $file_imports{$file}=\%imps;
  next unless $file=~m{/internal/};
  my @ls=split/\n/,$c; for my $i(0..$#ls){ my $ln=$ls[$i]; next unless $ln=~/^func\s+(?:\(([^)]*)\)\s+)?([A-Za-z_]\w*)\s*\(/;
    my($rc,$nm)=($1//'',$2); next if $nm=~/^(Test|Benchmark|Example|Fuzz)/||$nm eq 'init';
    my $rt=''; $rt=$1 if $rc=~/\*?\s*([A-Za-z_]\w*)\s*$/; my $pp=pkg_path($file);
    my $key=$rt?"$pp|$rt.$nm":"$pp|$nm";
    $decls{$key}={file=>$file,line=>$i+1,name=>$nm,recv=>$rt,pp=>$pp,pn=>$file_pkg{$file},kind=>$rt?'method':'func'};
  }
}
my %ppn; $ppn{$_->{pp}}=$_->{pn} for values %decls;
my %sites_all; my %sites_prod; my %sites_func_all; my %sites_func_prod;
my %sites_meth_sp; # same-package method calls only

sub add { my($k,$f,$l,$bucket)=@_; return unless $decls{$k}; my $d=$decls{$k}; return if $f eq $d->{file}&&$l==$d->{line};
