      next unless $p;
      my $fk="$p|$n"; add($fk,$file,$l,'func') if $decls{$fk} && $decls{$fk}{kind} eq 'func';
      for my $k(keys %decls){ add($k,$file,$l,'meth') if $decls{$k}{pp} eq $p && $decls{$k}{name} eq $n && $decls{$k}{kind} eq 'method'; }
    }
