    if($fpp){ while($ln=~/(?<![A-Za-z0-9_\.])\b([A-Za-z_]\w*)\s*\(/g){ my $n=$1; next if grep{$_ eq $n}@kw; my $k="$fpp|$n"; add($k,$file,$l,'func') if $decls{$k}&&$decls{$k}{kind} eq 'func'; } }
