#!/usr/bin/perl
use strict; use warnings; use File::Basename;
my ($root,$module)=('/bench/repo','github.com/usememos/memos');
my @go_files = `find '$root' -name '*.go' ! -path '*/vendor/*' 2>/dev/null`; chomp @go_files;
my (%file_pkg,%file_imports,%decls);

sub pkg_path { my $f=shift; $f=~s{^\Q$root\E/}{}; $f=~s{/[^/]+$}{}; "$module/$f"; }

for my $file (@go_files) {
  open my $fh,'<',$file or next; my $c=do{local $/;<$fh>}; close $fh;
  $file_pkg{$file}=$1 if $c=~/^package\s+(\w+)/m;
  my %imps; while($c=~/^import\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)")/mg){
    my @ls=defined$2?qq{"$2"}:split/\n/,$1//''; for(@ls){next unless/"([^"]+)"/; my($p,$a)=($1,basename($1));$a=~s/-/_/g;$a=$1 if/^\s*(\w+)\s+"/;$imps{$a}=$p;}
  } $file_imports{$file}=\%imps;
  next unless $file=~m{/internal/};
  my @ls=split/\n/,$c; for my $i(0..$#ls){ my $ln=$ls[$i]; next unless $ln=~/^func\s+(?:\(([^)]*)\)\s+)?([A-Za-z_]\w*)\s*\(/;
    my($rc,$nm)=($1//'',$2); next if $nm=~/^(Test|Benchmark|Example|Fuzz)/||$nm eq 'init';
    my $rt=''; $rt=$1 if $rc=~/\*?\s*([A-Za-z_]\w*)\s*$/; my $pp=pkg_path($file);
    my $key=$rt?"$pp|$rt.$nm":"$pp|$nm";
    $decls{$key}={file=>$file,line=>$i+1,name=>$nm,recv=>$rt,pp=>$pp,pn=>$file_pkg{$file},kind=>$rt?'method':'func'};
  }
}
my %ppn; $ppn{$_->{pp}}=$_->{pn} for values %decls;
my %method_name_keys; for my $k(keys %decls){ push @{$method_name_keys{$decls{$k}{name}}}, $k if $decls{$k}{kind} eq 'method'; }
my %globally_unique_method = map { $_ => 1 } grep { @{$method_name_keys{$_}} == 1 } keys %method_name_keys;

my (%all,%prod,%prod_nocmd);
sub add { my($k,$f,$l)=@_; return unless $decls{$k}; my $d=$decls{$k}; return if $f eq $d->{file}&&$l==$d->{line};
  $all{$k}{"$f:$l"}=1; unless($f=~/_test\.go$/){ $prod{$k}{"$f:$l"}=1; $prod_nocmd{$k}{"$f:$l"}=1 unless $f=~m{/(cmd|scripts)/}; }
}
my @kw=qw(if for switch return func make new len cap append delete panic recover go defer map struct interface select range case default);

for my $file (@go_files) {
  open my $fh,'<',$file or next; my @ls=<$fh>; close $fh; my $imps=$file_imports{$file}//{};
  my $fpp = ($file=~m{/internal/}) ? pkg_path($file) : '';
  for my $i(0..$#ls){ my($ln,$l)=($ls[$i],$i+1); next if $ln=~/^\s*func\s+/;
    while($ln=~/\b([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(/g){ my($q,$n)=($1,$2); my $p=$imps->{$q};
      if(!$p){for my $a(keys%$imps){my $pn=$ppn{$imps->{$a}}//basename($imps->{$a}); if($pn eq $q){$p=$imps->{$a};last;}}}
      next unless $p;
      my $fk="$p|$n"; add($fk,$file,$l) if $decls{$fk} && $decls{$fk}{kind} eq 'func';
      for my $k(keys %decls){ add($k,$file,$l) if $decls{$k}{pp} eq $p && $decls{$k}{name} eq $n && $decls{$k}{kind} eq 'method'; }
    }
    if($fpp){ while($ln=~/(?<![A-Za-z0-9_\.])\b([A-Za-z_]\w*)\s*\(/g){ my $n=$1; next if grep{$_ eq $n}@kw; my $k="$fpp|$n"; add($k,$file,$l) if $decls{$k}&&$decls{$k}{kind} eq 'func'; } }
    while($ln=~/\.([A-Za-z_]\w*)\s*\(/g){ my $n=$1; next unless $globally_unique_method{$n}; add($method_name_keys{$n}[0],$file,$l); }
  }
}

sub top { my($h,$title,$n)=@_; print "$title\n"; my @r=sort{(scalar(keys%{$h->{$b}//{}}))<=>(scalar(keys%{$h->{$a}//{}}))} keys %decls; my $shown=0;
  for my $k(@r){ my $ct=scalar keys %{$h->{$k}//{}}; next unless $ct>0; my $d=$decls{$k};
    printf "%4d  %s:%d  %s.%s%s (%s)\n",$ct,$d->{file},$d->{line},$d->{pn},$d->{recv}?"$d->{recv}.":'',$d->{name},$d->{kind};
    last if ++$shown>=$n; } print "\n"; }

print "Declarations scanned: ".scalar(keys %decls)."\n";
print "Globally unique method names: ".scalar(keys %globally_unique_method)."\n\n";
top(\%all,'ALL backend .go (incl tests):',15);
top(\%prod,'PROD only (exclude *_test.go call sites):',15);
top(\%prod_nocmd,'PROD excl tests+cmd/scripts call sites:',15);
PERL
